use super::*;
fn q(at:i64,bid:i128,ask:i128)->Quote{Quote{market:"1".into(),exchange:"101".into(),at,request:at-100,received:at-10,sequence:at,version:at.to_string(),bids:vec![(bid,1000)],asks:vec![(ask,1000)]}}
fn arm(case:Case,older:i128,recent:i128)->Arm{let mut a=Arm::new(case);for i in 0..=120{a.wallet.feature_bid("1",i*30000,if i<61{older}else{recent}).unwrap();}a}
#[test]fn exactly_one_tick_rise_is_admitted_flat_and_decline_denied(){let points=|old,new|(0..5).map(|i|(i,old)).chain((0..5).map(|i|(2_000_000+i,new))).collect::<Vec<_>>();assert!(strict_positive_trend(&points(350000,355000),3_600_000).0);assert_eq!(strict_positive_trend(&points(350000,350000),3_600_000).1,"flat_or_below_one_tick_rise");assert_eq!(strict_positive_trend(&points(350000,345000),3_600_000).1,"declining_recent_segment");}
#[test]fn four_points_in_one_segment_is_unknown_even_with_twenty_total(){let p=(0..16).map(|i|(i,350000)).chain((0..4).map(|i|(2_000_000+i,355000))).collect::<Vec<_>>();assert_eq!(strict_positive_trend(&p,3_600_000).1,"unknown_segment_coverage");}
#[test]fn timestamp_boundary_includes_exact_split_in_recent_segment(){let p=(0..5).map(|i|(i,350000)).chain((0..5).map(|i|(1_800_000+i,355000))).collect::<Vec<_>>();assert!(strict_positive_trend(&p,3_600_000).0);}
#[test]fn flat_trend_blocks_only_new_entry_while_cap_control_remains_exact(){let quote=q(3_610_000,325000,330000);let mut filtered=arm(Case::StrictPositiveThirtyThirty,350000,350000);let mut cap=arm(Case::OriginalReferenceCap,350000,350000);filtered.observe(quote.clone(),true,None,"row").unwrap();cap.observe(quote,true,None,"row").unwrap();assert!(filtered.wallet.pending.is_empty());assert!(cap.wallet.pending.contains_key("1"));assert_eq!(filtered.trend_counts["flat_or_below_one_tick_rise"],1);}
#[test]fn carried_buy_and_owned_exit_survive_later_nonpositive_trend(){let mut a=arm(Case::StrictPositiveThirtyThirty,345000,350000);a.observe(q(3_610_000,325000,330000),true,None,"first").unwrap();assert!(a.wallet.pending.contains_key("1"));for i in 0..60{a.wallet.feature_bid("1",3_611_000+i,300000).unwrap();}a.observe(q(3_615_000,325000,330000),true,None,"second").unwrap();assert_eq!(a.wallet.positions["1"].cost,330000);a.observe(q(3_620_000,335000,340000),true,None,"third").unwrap();a.observe(q(3_625_000,335000,340000),true,None,"fourth").unwrap();assert!(a.wallet.positions.is_empty());assert_eq!(a.wallet.realized,5000);}
